def bounds(g):
    # boundary lines/cols are full 8 rows
    h=len(g); w=len(g[0])
    return [i for i in range(h) if all(x==8 for x in g[i])], [j for j in range(w) if all(g[i][j]==8 for i in range(h))]

def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    br=[i for i in range(h) if all(x==8 for x in g[i])]
    bc=[j for j in range(w) if all(g[i][j]==8 for j==j for i in range(h))] if False else [j for j in range(w) if all(g[i][j]==8 for i in range(h))]
    # cell band index for each non-8 row/col
    def band(idx,bnds):
        k=0
        for b in bnds:
            if idx>b: k+=1
        return k
    from collections import defaultdict
    pos=defaultdict(list)
    for i in range(h):
        for j in range(w):
            if g[i][j] in (2,3): pos[g[i][j]].append((band(i,br),band(j,bc)))
    segs=defaultdict(set)  # color -> set of (cr,cc)
    for c,ps in pos.items():
        for a in range(len(ps)):
            for b in range(a+1,len(ps)):
                (r1,c1),(r2,c2)=ps[a],ps[b]
                if r1==r2:
                    for cc in range(min(c1,c2),max(c1,c2)+1): segs[c].add((r1,cc))
                elif c1==c2:
                    for rr in range(min(r1,r2),max(r1,r2)+1): segs[c].add((rr,c1))
    out=[[0]*w for _ in range(h)]
    # compute cell color map with overlap
    cellmap={}
    for c in (2,3):
        for cell in segs[c]:
            cellmap.setdefault(cell,[]).append(c)
    for (cr,cc),cs in cellmap.items():
        col=6 if len(cs)>1 else cs[0]
        # fill cell
        rs=[i for i in range(h) if band(i,br)==cr]
        cls=[j for j in range(w) if band(j,bc)==cc]
        for i in rs:
            for j in cls:
                out[i][j]=col
    return out

